// Formatage des données pour l'affichage
const articles = $input.first().json.result.articles;
const totalCount = $input.first().json.result.total_count;
const lastUpdated = $input.first().json.result.last_updated;

// Création du HTML pour l'affichage
let htmlContent = `
<div class="ai-news-container">
  <h2>🤖 Veille IA ArchiaTech</h2>
  <p class="meta-info">📊 ${totalCount} articles • ⏰ ${new Date(lastUpdated).toLocaleString('fr-FR')}</p>
  <div class="articles-grid">
`;

articles.forEach((article, index) => {
  const imageHtml = article.image_url ? 
    `<img src="${article.image_url}" alt="${article.title}" class="article-image" onerror="this.style.display='none'">` : 
    `<div class="no-image">📰</div>`;

  htmlContent += `
    <article class="news-card" data-index="${index}">
      <div class="article-header">
        ${imageHtml}
        <div class="article-meta">
          <span class="source">${article.source}</span>
          <span class="category">${article.category}</span>
        </div>
      </div>
      <div class="article-content">
        <h3 class="article-title">${article.title}</h3>
        <p class="article-description">${article.description || 'Aucune description disponible.'}</p>
        <div class="article-footer">
          <a href="${article.url}" target="_blank" class="read-more">
            Lire l'article →
          </a>
          ${article.published_at ? `<span class="publish-date">${new Date(article.published_at).toLocaleDateString('fr-FR')}</span>` : ''}
        </div>
      </div>
    </article>
  `;
});

htmlContent += `
  </div>
  <div class="footer">
    <p>🔄 Actualisé automatiquement par ArchiaTech</p>
  </div>
</div>

<style>
.ai-news-container {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
  background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
}

.ai-news-container h2 {
  color: #e60023;
  text-align: center;
  margin-bottom: 10px;
  font-size: 2.5rem;
}

.meta-info {
  text-align: center;
  color: #64748b;
  margin-bottom: 30px;
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 20px;
}

.news-card {
  background: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s, box-shadow 0.2s;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
}

.article-header {
  position: relative;
  height: 200px;
  overflow: hidden;
}

.article-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.no-image {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #e60023, #ff1744);
  color: white;
  font-size: 3rem;
}

.article-meta {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  gap: 8px;
}

.source, .category {
  background: rgba(0, 0, 0, 0.7);
  color: white;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.8rem;
}

.category {
  background: #e60023;
}

.article-content {
  padding: 20px;
}

.article-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: #1e293b;
  margin-bottom: 10px;
  line-height: 1.4;
}

.article-description {
  color: #64748b;
  line-height: 1.6;
  margin-bottom: 15px;
}

.article-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.read-more {
  color: #e60023;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.2s;
}

.read-more:hover {
  color: #ff1744;
}

.publish-date {
  color: #94a3b8;
  font-size: 0.9rem;
}

.footer {
  text-align: center;
  margin-top: 40px;
  padding: 20px;
  color: #64748b;
  border-top: 1px solid #e2e8f0;
}

@media (max-width: 768px) {
  .articles-grid {
    grid-template-columns: 1fr;
  }

  .ai-news-container h2 {
    font-size: 2rem;
  }
}
</style>
`;

// Création du JSON pour API
const jsonResponse = {
  success: true,
  timestamp: new Date().toISOString(),
  source: "ArchiaTech MCP Server",
  data: {
    total_count: totalCount,
    last_updated: lastUpdated,
    articles: articles.map(article => ({
      id: `article_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      title: article.title,
      description: article.description,
      url: article.url,
      image_url: article.image_url,
      source: article.source,
      category: article.category,
      published_at: article.published_at
    }))
  }
};

return {
  html: htmlContent,
  json: jsonResponse,
  total_articles: totalCount,
  last_updated: lastUpdated
};
